contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0, "deposit must be positive");
        require(collectAmount <= depositAmount, "collect at most deposit");
        require(address(this).balance >= depositAmount, "insufficient balance");

        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;

        bool reverted = true;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;

        assert(
            (reverted && balAfter == balBefore && cBalAfter == cBalBefore) ||
            (!reverted && balAfter == balBefore - collectAmount && cBalAfter == cBalBefore - collectAmount)
        );
    }

    receive() external payable {}
}

